# app.py
import re
import textwrap
from dataclasses import dataclass
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple

import viktor as vkt
from viktor import Color, TableCell


try:
    import ifcopenshell
    import ifcopenshell.util.element
except Exception:  # pragma: no cover
    ifcopenshell = None


LOAD_CAPACITY_DEFAULT_KEYWORDS = "capacity,resistance,ultimate,allowable,design load,nrd,mrd,vrd"  # free text
MATERIAL_GRADE_DEFAULT_KEYWORDS = "grade,strength class,yield strength,fy,f_y,fu,f_u"  # free text
FIRE_RATING_DEFAULT_KEYWORDS = "firerating,fire rating,fire resistance"  # free text
STEEL_DETECTION_DEFAULT_KEYWORDS = "steel"  # free text


@dataclass
class MemberQCRow:
    ifc_id: int
    global_id: str
    ifc_type: str
    name: str
    storey: str
    material: str
    is_steel: bool
    has_load_capacity: bool
    has_material_grade: bool
    has_fire_rating: bool
    missing: List[str]


def _split_keywords(s: Optional[str]) -> List[str]:
    if not s:
        return []
    return [k.strip().lower() for k in str(s).split(",") if k.strip()]


def _has_value(v: Any) -> bool:
    if v is None:
        return False
    if isinstance(v, str):
        return bool(v.strip()) and v.strip().lower() not in {"n/a", "na", "none", "null", "-"}
    if isinstance(v, (int, float)):
        # treat numeric 0 as absent for metadata checks
        return abs(float(v)) > 0.0
    if isinstance(v, bool):
        return v
    return True


def _safe_str(v: Any) -> str:
    if v is None:
        return ""
    try:
        return str(v)
    except Exception:
        return ""


def _open_ifc_from_viktor_file(viktor_file: vkt.File):
    if ifcopenshell is None:
        raise vkt.UserError(
            "IfcOpenShell is not available. Add 'ifcopenshell' to requirements.txt and rebuild the app."
        )

    raw = viktor_file.getvalue()
    if not raw:
        raise vkt.UserError("The uploaded IFC file is empty.")

    temp_path = None
    try:
        with NamedTemporaryFile(suffix=".ifc", delete=False) as tf:
            tf.write(raw)
            temp_path = Path(tf.name)
        model = ifcopenshell.open(str(temp_path))
        return model
    except Exception as e:
        raise vkt.UserError(f"Could not read IFC: {e}")
    finally:
        if temp_path and temp_path.exists():
            try:
                temp_path.unlink()
            except Exception:
                pass


def _get_storey_name(element) -> str:
    try:
        storey = ifcopenshell.util.element.get_container(element)
        if storey is None:
            return ""
        return _safe_str(getattr(storey, "Name", ""))
    except Exception:
        return ""


def _get_material_names(element) -> List[str]:
    """Returns a list of material names (best-effort).

    Note: util.get_material may return an entity, a string, or a list.
    """
    try:
        mat = ifcopenshell.util.element.get_material(element)
    except Exception:
        mat = None

    if mat is None:
        return []

    # IfcOpenShell sometimes returns IfcMaterial entities, sometimes names.
    if isinstance(mat, (list, tuple, set)):
        mats = list(mat)
    else:
        mats = [mat]

    out = []
    for m in mats:
        if hasattr(m, "Name"):
            out.append(_safe_str(m.Name))
        else:
            out.append(_safe_str(m))

    # de-dup while keeping order
    seen = set()
    uniq = []
    for name in out:
        n = name.strip()
        if not n:
            continue
        if n.lower() in seen:
            continue
        seen.add(n.lower())
        uniq.append(n)
    return uniq


def _collect_psets_from_object(obj) -> Dict[str, Dict[str, Any]]:
    try:
        # get_psets returns: {'Pset_X': {'Prop': val, ...}, 'Qto_Y': {...}}
        return ifcopenshell.util.element.get_psets(obj) or {}
    except Exception:
        return {}


def _collect_psets_instance_and_type(element) -> Dict[str, Dict[str, Any]]:
    """Collect psets on the instance and (if available) on the relating type."""
    psets = _collect_psets_from_object(element)

    # Merge type psets (common in IFC authoring workflows)
    try:
        for rel in getattr(element, "IsDefinedBy", []) or []:
            if rel and rel.is_a("IfcRelDefinesByType"):
                type_obj = rel.RelatingType
                t_psets = _collect_psets_from_object(type_obj)
                for pset_name, props in t_psets.items():
                    if pset_name not in psets:
                        psets[pset_name] = props
                    else:
                        # don't overwrite instance values
                        for k, v in (props or {}).items():
                            if k not in psets[pset_name]:
                                psets[pset_name][k] = v
    except Exception:
        pass

    return psets


def _flatten_props(psets: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
    """Flatten properties for fuzzy lookup.

    Keys include both 'prop' and 'pset.prop' (lowercased).
    """
    flat: Dict[str, Any] = {}
    for pset_name, props in (psets or {}).items():
        if not isinstance(props, dict):
            continue
        pset_l = _safe_str(pset_name).lower()
        for prop_name, val in props.items():
            prop_l = _safe_str(prop_name).lower()
            if not prop_l:
                continue
            # Prefer first seen for generic prop key
            flat.setdefault(prop_l, val)
            flat[f"{pset_l}.{prop_l}"] = val
    return flat


def _find_any_keyword_value(flat_props: Dict[str, Any], keywords: Sequence[str], *,
                            exclude_exact: Sequence[str] = ()) -> Tuple[bool, Optional[Tuple[str, Any]]]:
    """Return (found, (matched_key, value)).

    keyword matching is case-insensitive and searches both exact and substring matches in keys.
    """
    excludes = {e.lower() for e in exclude_exact}
    for key, val in (flat_props or {}).items():
        if key.lower() in excludes:
            continue
        key_l = key.lower()
        for kw in keywords:
            kw_l = kw.lower()
            if not kw_l:
                continue
            if key_l == kw_l or kw_l in key_l:
                if _has_value(val):
                    return True, (key, val)
    return False, None


def _is_steel(material_names: Sequence[str], steel_keywords: Sequence[str]) -> bool:
    if not material_names:
        return False
    mats = " ".join(material_names).lower()

    if any(kw in mats for kw in steel_keywords if kw):
        return True

    # Also detect common steel grade patterns (e.g., S355, S275)
    if re.search(r"\bS\s*\d{3,4}\b", " ".join(material_names), flags=re.IGNORECASE):
        return True

    # ASTM patterns (very approximate)
    if re.search(r"\bA\s*\d{2,4}\b", " ".join(material_names), flags=re.IGNORECASE):
        return True

    return False


def _has_grade_in_material_string(material_names: Sequence[str]) -> bool:
    if not material_names:
        return False
    text = " ".join(material_names)
    if re.search(r"\bS\s*\d{3,4}\b", text, flags=re.IGNORECASE):
        return True
    if re.search(r"\bC\s*\d{2,3}\s*/\s*\d{2,3}\b", text, flags=re.IGNORECASE):
        return True
    if re.search(r"\bA\s*\d{2,4}\b", text, flags=re.IGNORECASE):
        return True
    return False


def _get_structural_members(model, include_ifc_member: bool) -> List[Any]:
    types = ["IfcBeam", "IfcColumn"]
    if include_ifc_member:
        types.append("IfcMember")

    elems: List[Any] = []
    seen_ids = set()
    for t in types:
        for e in model.by_type(t) or []:
            try:
                sid = int(e.id())
            except Exception:
                sid = None
            if sid is not None and sid in seen_ids:
                continue
            if sid is not None:
                seen_ids.add(sid)
            elems.append(e)
    return elems


def _qc_members(
    model,
    *,
    load_keywords: Sequence[str],
    grade_keywords: Sequence[str],
    fire_keywords: Sequence[str],
    steel_keywords: Sequence[str],
    require_load_capacity: bool,
    require_fire_rating: bool,
    require_material_grade_for_all: bool,
    include_ifc_member: bool,
    max_elements: int,
) -> List[MemberQCRow]:
    members = _get_structural_members(model, include_ifc_member=include_ifc_member)
    if max_elements and len(members) > max_elements:
        members = members[:max_elements]

    rows: List[MemberQCRow] = []

    for element in members:
        ifc_id = int(element.id())
        global_id = _safe_str(getattr(element, "GlobalId", ""))
        ifc_type = _safe_str(element.is_a())
        name = _safe_str(getattr(element, "Name", ""))
        storey = _get_storey_name(element)

        material_names = _get_material_names(element)
        material_txt = ", ".join(material_names)
        is_steel = _is_steel(material_names, steel_keywords)

        psets = _collect_psets_instance_and_type(element)
        flat = _flatten_props(psets)

        # Fire rating is usually a dedicated property (e.g., Pset_BeamCommon.FireRating)
        has_fire_rating, _ = _find_any_keyword_value(flat, fire_keywords)

        # Load capacity: best-effort fuzzy search. Exclude 'LoadBearing' because it's not a capacity.
        has_load_capacity, _ = _find_any_keyword_value(
            flat,
            load_keywords,
            exclude_exact=["loadbearing", "pset_beamcommon.loadbearing", "pset_columncommon.loadbearing"],
        )

        # Material grade: either explicit properties or detectable in material name
        has_material_grade_props, _ = _find_any_keyword_value(flat, grade_keywords)
        has_material_grade = bool(has_material_grade_props or _has_grade_in_material_string(material_names))

        missing: List[str] = []
        if require_load_capacity and not has_load_capacity:
            missing.append("load capacity")
        if require_fire_rating and not has_fire_rating:
            missing.append("fire rating")

        # By default only enforce grade for steel (explicitly requested pain point)
        if require_material_grade_for_all:
            if not has_material_grade:
                missing.append("material grade")
        else:
            if is_steel and not has_material_grade:
                missing.append("material grade (steel)")

        rows.append(
            MemberQCRow(
                ifc_id=ifc_id,
                global_id=global_id,
                ifc_type=ifc_type,
                name=name,
                storey=storey,
                material=material_txt,
                is_steel=is_steel,
                has_load_capacity=has_load_capacity,
                has_material_grade=has_material_grade,
                has_fire_rating=has_fire_rating,
                missing=missing,
            )
        )

    return rows


def _bool_cell(ok: bool) -> TableCell:
    if ok:
        return TableCell("Yes", background_color=Color(223, 245, 232), text_color=Color(0, 96, 42), text_style="bold")
    return TableCell("No", background_color=Color(255, 228, 228), text_color=Color(140, 0, 0), text_style="bold")


def _status_cell(ok: bool) -> TableCell:
    if ok:
        return TableCell("OK", background_color=Color(223, 245, 232), text_color=Color(0, 96, 42), text_style="bold")
    return TableCell("INCOMPLETE", background_color=Color(255, 228, 228), text_color=Color(140, 0, 0), text_style="bold")


class Parametrization(vkt.Parametrization):
    main = vkt.Page("Structural member QC", views=["summary_view", "member_table", "ifc_view"], width=40)

    main.inputs = vkt.Section("Upload")
    main.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Structural Member Properties Check

            Upload an IFC model and review whether **beams** and **columns** have key safety/compliance metadata.

            **Checks (best-effort):**
            - Load capacity (fuzzy keyword scan in property sets)
            - Material grade (especially enforced for **steel** members)
            - Fire rating

            Use the table to identify missing metadata.
            """
        )
    )
    main.inputs.ifc = vkt.FileField("IFC file")
    main.inputs.geometry = vkt.GeometrySelectField("Select an element (optional, for IFC view)")

    main.checks = vkt.Section("Check settings")
    main.checks.require_load_capacity = vkt.BooleanField("Require load capacity metadata", default=True)
    main.checks.require_fire_rating = vkt.BooleanField("Require fire rating metadata", default=True)
    main.checks.require_material_grade_for_all = vkt.BooleanField(
        "Require material grade for all members (otherwise only enforced for steel)", default=False
    )
    main.checks.include_ifc_member = vkt.BooleanField("Include IfcMember elements (in addition to beams/columns)", default=True)

    main.checks.max_elements = vkt.NumberField(
        "Max members to scan (performance safeguard)", default=5000, min=1, step=1
    )

    main.checks.load_keywords = vkt.TextField("Load capacity keywords (comma-separated)", default=LOAD_CAPACITY_DEFAULT_KEYWORDS)
    main.checks.grade_keywords = vkt.TextField("Material grade keywords (comma-separated)", default=MATERIAL_GRADE_DEFAULT_KEYWORDS)
    main.checks.fire_keywords = vkt.TextField("Fire rating keywords (comma-separated)", default=FIRE_RATING_DEFAULT_KEYWORDS)
    main.checks.steel_keywords = vkt.TextField("Steel detection keywords (comma-separated)", default=STEEL_DETECTION_DEFAULT_KEYWORDS)


class Controller(vkt.Controller):
    label = "Structural Member Properties Check"
    parametrization = Parametrization

    def _get_rows(self, params) -> List[MemberQCRow]:
        if not getattr(params.main.inputs, "ifc", None) or not params.main.inputs.ifc.file:
            return []

        model = _open_ifc_from_viktor_file(params.main.inputs.ifc.file)

        rows = _qc_members(
            model,
            load_keywords=_split_keywords(params.main.checks.load_keywords),
            grade_keywords=_split_keywords(params.main.checks.grade_keywords),
            fire_keywords=_split_keywords(params.main.checks.fire_keywords),
            steel_keywords=_split_keywords(params.main.checks.steel_keywords),
            require_load_capacity=bool(params.main.checks.require_load_capacity),
            require_fire_rating=bool(params.main.checks.require_fire_rating),
            require_material_grade_for_all=bool(params.main.checks.require_material_grade_for_all),
            include_ifc_member=bool(params.main.checks.include_ifc_member),
            max_elements=int(params.main.checks.max_elements or 0),
        )
        return rows

    @vkt.DataView("Summary")
    def summary_view(self, params, **kwargs):
        if not getattr(params.main.inputs, "ifc", None) or not params.main.inputs.ifc.file:
            data = vkt.DataGroup(
                vkt.DataItem(
                    "IFC upload",
                    "No file",
                    status=vkt.DataStatus.WARNING,
                    status_message="Upload an IFC file to run the checks.",
                )
            )
            return vkt.DataResult(data)

        rows = self._get_rows(params)
        total = len(rows)
        if total == 0:
            data = vkt.DataGroup(
                vkt.DataItem(
                    "Members found",
                    0,
                    status=vkt.DataStatus.WARNING,
                    status_message="No IfcBeam/IfcColumn (and optionally IfcMember) elements were found.",
                )
            )
            return vkt.DataResult(data)

        incomplete = [r for r in rows if r.missing]
        n_incomplete = len(incomplete)

        beams = sum(1 for r in rows if r.ifc_type.lower().startswith("ifcbeam"))
        cols = sum(1 for r in rows if r.ifc_type.lower().startswith("ifccolumn"))
        members = sum(1 for r in rows if r.ifc_type.lower().startswith("ifcmember"))

        data = vkt.DataGroup(
            vkt.DataItem("Members scanned", total),
            vkt.DataItem("Beams", beams),
            vkt.DataItem("Columns", cols),
            vkt.DataItem("IfcMember", members),
            vkt.DataItem(
                "Incomplete members",
                n_incomplete,
                status=vkt.DataStatus.WARNING if n_incomplete else vkt.DataStatus.SUCCESS,
                status_message="Some members are missing required metadata." if n_incomplete else "All members meet the configured checks.",
            ),
        )
        return vkt.DataResult(data)

    @vkt.TableView("Member property completeness")
    def member_table(self, params, **kwargs):
        if not getattr(params.main.inputs, "ifc", None) or not params.main.inputs.ifc.file:
            return vkt.TableResult(
                [],
                column_headers=[
                    "IFC ID",
                    "GlobalId",
                    "Type",
                    "Name",
                    "Storey",
                    "Material",
                    "Steel?",
                    "Load capacity?",
                    "Material grade?",
                    "Fire rating?",
                    "Missing",
                    "Status",
                ],
            )

        rows = self._get_rows(params)

        table: List[List[Any]] = []
        for r in rows:
            ok = len(r.missing) == 0
            missing_txt = ", ".join(r.missing)
            missing_cell = (
                TableCell(missing_txt, background_color=Color(255, 228, 228), text_color=Color(140, 0, 0))
                if missing_txt
                else TableCell("", background_color=Color(223, 245, 232), text_color=Color(0, 96, 42))
            )

            table.append(
                [
                    r.ifc_id,
                    r.global_id,
                    r.ifc_type,
                    r.name,
                    r.storey,
                    r.material,
                    _bool_cell(r.is_steel),
                    _bool_cell(r.has_load_capacity),
                    _bool_cell(r.has_material_grade),
                    _bool_cell(r.has_fire_rating),
                    missing_cell,
                    _status_cell(ok),
                ]
            )

        return vkt.TableResult(
            table,
            column_headers=[
                "IFC ID",
                "GlobalId",
                "Type",
                "Name",
                "Storey",
                "Material",
                "Steel?",
                "Load capacity?",
                "Material grade?",
                "Fire rating?",
                "Missing",
                "Status",
            ],
        )

    @vkt.IFCAndDataView("IFC model (select an element to inspect properties)", x_axis_to_right=True)
    def ifc_view(self, params, **kwargs):
        if not getattr(params.main.inputs, "ifc", None) or not params.main.inputs.ifc.file:
            # IFCAndDataView requires an IFC file; raise a clear message.
            raise vkt.UserError("Upload an IFC file to view the model.")

        ifc_file = params.main.inputs.ifc.file

        if not params.main.inputs.geometry:
            data = vkt.DataGroup(
                vkt.DataItem(
                    "Selection",
                    "None",
                    status=vkt.DataStatus.INFO,
                    status_message="Select an element in the viewer to list its property sets.",
                )
            )
            return vkt.IFCAndDataResult(ifc=ifc_file, data=data)

        model = _open_ifc_from_viktor_file(ifc_file)
        try:
            elem = model.by_id(int(params.main.inputs.geometry))
        except Exception:
            elem = None

        if elem is None:
            data = vkt.DataGroup(
                vkt.DataItem(
                    "Selection",
                    "Invalid",
                    status=vkt.DataStatus.ERROR,
                    status_message="Could not resolve the selected element id.",
                )
            )
            return vkt.IFCAndDataResult(ifc=ifc_file, data=data)

        psets = _collect_psets_instance_and_type(elem)
        data_items: List[vkt.DataItem] = []

        data_items.append(vkt.DataItem("IFC type", elem.is_a()))
        data_items.append(vkt.DataItem("IFC ID", int(elem.id())))
        data_items.append(vkt.DataItem("GlobalId", _safe_str(getattr(elem, "GlobalId", ""))))
        data_items.append(vkt.DataItem("Name", _safe_str(getattr(elem, "Name", ""))))

        mats = _get_material_names(elem)
        data_items.append(vkt.DataItem("Material(s)", ", ".join(mats)))

        for pset_name, props in (psets or {}).items():
            if not isinstance(props, dict):
                continue
            sub_items = [vkt.DataItem(k, _safe_str(v)) for k, v in props.items()]
            data_items.append(vkt.DataItem(pset_name, "", subgroup=vkt.DataGroup(*sub_items)))

        data = vkt.DataGroup(*data_items)
        return vkt.IFCAndDataResult(ifc=ifc_file, data=data)
